const fs = require('fs');
const item = $input.first().json;

let prompt = fs.readFileSync('/prompts/summarize.md', 'utf8');
prompt = prompt
  .replace('{{title}}', item.title || '')
  .replace('{{source}}', item.source_name || '')
  .replace('{{url}}', item.url || '')
  .replace('{{content}}', (item.content || '').slice(0, 6000));

return [{ json: { ...item, prompt } }];

const item = $input.first().json;
const articleId = $('Get Articles to Summarize').first().json.id;

let result;
try {
  result = JSON.parse(item.choices[0].message.content);
} catch(e) {
  return [{ json: { article_id: articleId, error: 'JSON parse failed', raw: item.choices[0].message.content } }];
}

const tokensUsed = item.usage?.total_tokens || 0;
const costUsd = (tokensUsed / 1000) * 0.00015; // gpt-4o-mini pricing

return [{ json: { article_id: articleId, ...result, tokens_used: tokensUsed, cost_usd: costUsd } }];

