UPDATE articles SET summary = '{{ $json.summary }}', key_points = '{{ JSON.stringify($json.key_points) }}'::jsonb, entities = '{{ JSON.stringify($json.entities) }}'::jsonb, topics = ARRAY[{{ $json.topics?.map(t => `'${t}'`).join(',') }}], sentiment = '{{ $json.sentiment }}', quality_score = {{ $json.quality_score || 0 }}, status = 'scored', updated_at = NOW() WHERE id = '{{ $json.article_id }}'::uuid;

INSERT INTO summaries (article_id, model, summary, key_points, tokens_used, cost_usd)
VALUES ('{{ $json.article_id }}'::uuid, 'gpt-4o-mini', '{{ $json.summary }}', '{{ JSON.stringify($json.key_points) }}'::jsonb, {{ $json.tokens_used }}, {{ $json.cost_usd }});
